   Fonts: 5 Aptos faces base64-inlined for a self-contained report.
   ========================================================================== */

@font-face{
  font-family:'Aptos';
  font-weight:400;
  font-style:normal;
  font-display:swap;
  src:url(data:font/ttf;base64,) format('truetype');
}
@font-face{
  font-family:'Aptos';
  font-weight:600;
  font-style:normal;
  font-display:swap;
  src:url(data:font/ttf;base64,) format('truetype');
}
@font-face{
  font-family:'Aptos';
  font-weight:700;
  font-style:normal;
  font-display:swap;
  src:url(data:font/ttf;base64,) format('truetype');
}
@font-face{
  font-family:'Aptos Display';
  font-weight:700;
  font-style:normal;
  font-display:swap;
  src:url(data:font/ttf;base64,) format('truetype');
}
@font-face{
  font-family:'Aptos Mono';
  font-weight:400;
  font-style:normal;
  font-display:swap;
  src:url(data:font/ttf;base64,) format('truetype');
}

:root {

  /* ============================================================
     PRIMARY PALETTE  (Brand Style Guide p. 16)
     ============================================================ */
  --def-blue:        #0D2C71;   /* Definian Blue — PMS 2748 */
  --def-green:       #00AB63;   /* Definian Green — PMS 3405 */
  --def-white:       #FFFFFF;

  /* Aliases for the legacy names used in deck templates */
  --def-navy:        #0D2C71;   /* alias of def-blue */

  /* ============================================================
     SECONDARY PALETTE  (Brand Style Guide p. 16)
     ============================================================ */
  --def-midnight:    #02072D;   /* PMS 533 — primary dark background */
  --def-cool-gray:   #D8D7EE;   /* PMS Cool Gray 1 */
  --def-dark-gray:   #3C405B;   /* divider lines / borders on midnight */

  /* Aliases */
  --def-deep:        #02072D;   /* alias of def-midnight */
  --def-mist:        #D8D7EE;   /* alias of def-cool-gray */
  --def-slate:       #3C405B;   /* alias of def-dark-gray */
  --def-black:       #000000;
  --def-ink:         #02072D;   /* primary body color on light bg */

  /* ============================================================
     TERTIARY — CHART/DATA-VIZ ONLY  (Brand Style Guide p. 18)
     Apply only in the sequence shown in the guide.
     ============================================================ */
  --def-chart-1:     #00AB63;   /* Definian Green */
  --def-chart-2:     #0D2C71;   /* Definian Blue  */
  --def-chart-3:     #038FBA;   /* PMS 2203 */
  --def-chart-4:     #69D9FA;   /* PMS 305  */
  --def-chart-5:     #338261;   /* PMS 7724 */
  --def-chart-6:     #99DEC2;   /* PMS 337  */
  --def-chart-7:     #D8D7EE;   /* Cool Gray 1 */
  --def-chart-8:     #3C405B;   /* Dark Gray */

  /* ============================================================
     SUPPORT TONES
     ============================================================ */
  --def-watermark:   #F6F6F8;   /* tone-on-tone logo watermark on white */
  --def-green-bright:#00FF99;   /* hero-graphic accent (44% opacity, blur 8) */

  /* ============================================================
     SCALES — derived for component states (hovers, fills, borders).
     Use sparingly; foundations above are canonical.
     ============================================================ */

  /* Greens */
  --def-green-50:    #E6F7EF;
  --def-green-100:   #B3E8CF;
  --def-green-200:   #80D9AF;
  --def-green-300:   #4DCA8F;
  --def-green-400:   #1ABB6F;
  --def-green-500:   #00AB63;   /* brand */
  --def-green-600:   #00955A;
  --def-green-700:   #007A48;
  --def-green-800:   #005F38;
  --def-green-900:   #003D24;

  /* Blues */
  --def-blue-50:     #E7EBF4;
  --def-blue-100:    #B6C1DD;
  --def-blue-200:    #8497C6;
  --def-blue-300:    #536DAF;
  --def-blue-400:    #214398;
  --def-blue-500:    #0D2C71;   /* brand */
  --def-blue-600:    #0A2358;
  --def-blue-700:    #071940;
  --def-blue-800:    #04102B;
  --def-blue-900:    #02072D;   /* midnight */

  /* Neutrals (built around the cool-gray + dark-gray brand neutrals) */
  --def-neutral-0:   #FFFFFF;
  --def-neutral-50:  #F6F6F8;   /* watermark tone */
  --def-neutral-100: #EEEEF3;
  --def-neutral-200: #D8D7EE;   /* cool gray */
  --def-neutral-300: #B8B7CC;
  --def-neutral-400: #8A8AA0;
  --def-neutral-500: #5E6079;
  --def-neutral-600: #4B4E68;
  --def-neutral-700: #3C405B;   /* dark gray */
  --def-neutral-800: #1F2238;
  --def-neutral-900: #02072D;   /* midnight */

  /* ============================================================
     SEMANTIC FOREGROUND / BACKGROUND
     ============================================================ */
  --fg-1:        var(--def-midnight);     /* primary body on light */
  --fg-2:        var(--def-neutral-600);  /* secondary text */
  --fg-3:        var(--def-neutral-500);  /* captions */
  --fg-muted:    var(--def-neutral-400);
  --fg-on-dark:  var(--def-white);
  --fg-on-brand: var(--def-white);
  --fg-link:     var(--def-blue);
  --fg-link-hover: var(--def-green);

  --bg-1:        var(--def-white);
  --bg-2:        #F6F6F8;
  --bg-3:        var(--def-cool-gray);
  --bg-dark:     var(--def-midnight);     /* primary dark surface */
  --bg-blue:     var(--def-blue);
  --bg-green:    var(--def-green);

  --border-subtle:  var(--def-cool-gray);
  --border-strong:  var(--def-neutral-300);
  --border-on-dark: var(--def-dark-gray); /* per guide: borders on midnight */

  /* Status (derived; not codified in guide) */
  --status-success: var(--def-green);
  --status-warning: #E5A100;
  --status-error:   #D64545;
  --status-info:    var(--def-blue-400);

  /* ============================================================
     TYPE FAMILIES
     Aptos / Aptos SemiBold are the canonical Definian faces.
     Inter Tight is the free fallback that ships with this system.
     ============================================================ */
  --font-display: "Aptos Display", "Aptos", Arial, "Segoe UI",
                  "Inter Tight", system-ui, -apple-system, sans-serif;
  --font-sans:    "Aptos", Arial, "Segoe UI", "Inter Tight",
                  system-ui, -apple-system, "Helvetica Neue", sans-serif;
  --font-narrow:  "Aptos Narrow", "Aptos", Arial, "Inter Tight", system-ui, sans-serif;
  --font-serif:   "Aptos Serif", Georgia, "Times New Roman", serif;
  --font-mono:    "Aptos Mono", "JetBrains Mono", ui-monospace, "SF Mono", Menlo,
                  Consolas, "Courier New", monospace;

  /* ============================================================
     DESKTOP TYPE STYLES
     Sizes from the Brand Style Guide Desktop spec (p. 21);
     mapped to Aptos / Aptos SemiBold.
     ============================================================ */

  /* Headlines — Aptos SemiBold (600) */
  --fs-h1:         72px;   --lh-h1: 76px;   /* H1 Desktop, SemiBold 600 */
  --fs-h2:         44px;   --lh-h2: 48px;   /* H2 Desktop, Regular  400 */
  --fs-h3:         36px;   --lh-h3: 40px;   /* H3 Desktop, SemiBold 600 */
  --fs-h4:         32px;   --lh-h4: 40px;   /* H4 Desktop, Regular  400 */
  --fs-eyebrow:    24px;   --lh-eyebrow: 24px;  /* Aptos SemiBold 600 */

  /* Body — Aptos Regular (400) */
  --fs-body:       16px;   --lh-body: 24px;
  --fs-body-lg:    18px;   --lh-body-lg: 28px;
  --fs-small:      14px;   --lh-small: 20px;
  --fs-caption:    12px;   --lh-caption: 16px;
  --fs-overline:   11px;   --lh-overline: 16px;

  /* Display (deck hero — bigger than H1) */
  --fs-display:    96px;   --lh-display: 100px;

  /* ============================================================
     WEIGHTS
     ============================================================ */
  --fw-light:    300; 
  --fw-regular:  400;        /* Aptos Regular */
  --fw-medium:   500; 
  --fw-semibold: 600;        /* Aptos SemiBold */
  --fw-bold:     700;        /* Aptos Bold */

  /* ============================================================
     TRACKING
     ============================================================ */
  --ls-tight:    -0.01em; 
  --ls-display:  -0.02em; 
  --ls-normal:    0; 
  --ls-wide:      0.04em; 
  --ls-overline:  0.12em; 

  /* ============================================================
     SPACING SCALE (4pt grid)
     ============================================================ */
  --space-0:  0; 
  --space-1:  4px;
  --space-2:  8px;
  --space-3:  12px;
  --space-4:  16px;
  --space-5:  20px;
  --space-6:  24px;
  --space-8:  32px;
  --space-10: 40px;
  --space-12: 48px;
  --space-16: 64px;
  --space-20: 80px;
  --space-24: 96px;

  /* ============================================================
     RADII
     The brand "tight corner radius" (hero graphic, primary-icon
     bounding boxes) is small relative to size. We expose a set
     so components can opt into the right one.
     ============================================================ */
  --r-none: 0; 
  --r-sm:   4px;
  --r-md:   8px;
  --r-lg:   12px;
  --r-xl:   16px;
  --r-2xl:  24px;
  --r-pill: 999px;

  /* ============================================================
     ELEVATION
     Shadows tinted with midnight so they feel native to brand.
     ============================================================ */
  --shadow-xs: 0 1px 2px rgba(2, 7, 45, 0.06);
  --shadow-sm: 0 2px 6px rgba(2, 7, 45, 0.08);
  --shadow-md: 0 6px 18px rgba(2, 7, 45, 0.10);
  --shadow-lg: 0 18px 40px rgba(2, 7, 45, 0.14);
  --shadow-focus: 0 0 0 3px rgba(0, 171, 99, 0.35);

  /* ============================================================
     MOTION
     ============================================================ */
  --ease-out:    cubic-bezier(0.2, 0.8, 0.2, 1); 
  --ease-in-out: cubic-bezier(0.4, 0,   0.2, 1); 
  --dur-fast:    120ms; 
  --dur-base:    200ms; 
  --dur-slow:    360ms; 
}
